{
    int t, s, q, ans = 1;
    cin >> t >> s >> q;

    double loaded = s;
    double everysec = double(q - 1) / double(q);
    double reached = 0;

    while (reached < t)
    {
        reached += 1;
        loaded += everysec;

        if (reached > loaded)
        {
            loaded -= everysec;
            reached -= 1;

            double diff = loaded - reached;
            double delay = diff / (1 - everysec);
            reached = 1 - delay;
            ans++;
        }
    }

    cout << ans << '\n';
    return 0;
}

